void diagnostic_boundary(const char* substage,const char* method){contract_substage=substage;contract_method=method;}
void diagnostic_method(const char* method){contract_method=method;}
void diagnostic_stage(const char* stage){contract_stage=stage;diagnostic_boundary("entry","none");}
bool valid_owned_directory(const std::filesystem::path& path)noexcept{
    try{
        if(path.empty()||!path.is_absolute()||path.parent_path()!=owned_diagnostic_parent)return false;
        const auto name=path.filename().string();const std::string prefix="xmind-context-repository-";
        if(!name.starts_with(prefix)||name.size()==prefix.size()||name.size()>prefix.size()+10)return false;
        if(!std::all_of(name.begin()+static_cast<std::ptrdiff_t>(prefix.size()),name.end(),[](char c){return c>='0'&&c<='9';}))return false;
        const auto status=std::filesystem::symlink_status(path);
        return std::filesystem::is_directory(status)&&!std::filesystem::is_symlink(status)&&
            std::filesystem::canonical(path)==path&&std::filesystem::canonical(path.parent_path())==owned_diagnostic_parent;
    }catch(...){return false;}
}
bool private_failure_diagnostic(const std::exception& error,const char* error_class)noexcept{
    try{
        if(!valid_owned_directory(owned_diagnostic_directory))return false;
        const auto output=owned_diagnostic_directory/"private-contract-error.log";
        if(std::filesystem::exists(output)||std::filesystem::is_symlink(std::filesystem::symlink_status(output)))return false;
        std::ofstream log(output,std::ios::binary|std::ios::out);
        if(!log)return false;
        // Exception details may include SQL or synthetic payloads. They stay in
        // this retained disposable directory, never in public stdout/stderr.
        log<<"stage="<<contract_stage<<"\nsubstage="<<contract_substage<<"\nmethod="<<contract_method<<"\nclass="<<error_class<<"\nwhat=\n";
        constexpr std::size_t maximum_error_bytes=16384;
        const char* message=error.what();std::size_t bytes=0;
        if(message)while(bytes<maximum_error_bytes&&message[bytes]!='\0')++bytes;
        if(message)log.write(message,static_cast<std::streamsize>(bytes));
        log<<"\n";log.close();return static_cast<bool>(log);
    }catch(...){return false;}
}
void require(bool value,const char* reason){if(!value)throw std::runtime_error(reason);}
template<class E,class F>void rejects(F f,const char* reason){try{f();}catch(const E&){return;}throw std::runtime_error(reason);}
struct Directory {
    std::filesystem::path parent=std::filesystem::canonical(std::filesystem::temp_directory_path()),path=parent/("xmind-context-repository-"+std::to_string(std::random_device{}()));
    Directory(){require(std::filesystem::create_directory(path),"New disposable root required");owned_diagnostic_parent=parent;owned_diagnostic_directory=path;require(valid_owned_directory(path),"Disposable root must resolve to its exact owned temporary directory");}
    ~Directory(){if(contract_successful&&valid_owned_directory(path)){std::error_code ignored;std::filesystem::remove_all(path,ignored);}}
};
